function numTilings(n) {
  const MOD = 1000000007;
  const full = new Array(n + 1).fill(0);
  const partial = new Array(n + 1).fill(0);
  full[0] = 1;
  full[1] = 1;

  for (let i = 2; i <= n; i++) {
    full[i] = (full[i - 1] + full[i - 2] + 2 * partial[i - 1]) % MOD;
    partial[i] = (partial[i - 1] + full[i - 2]) % MOD;
  }
  return full[n];
}

