function numTilings(n) {
  // Place pieces cell by cell: always cover the first empty cell, column by column.
  // mask bits 0-1 are the two cells of column col, bits 2-3 those of column col + 1.
  const MOD = 1000000007;
  const pieces = [0b0011, 0b0101, 0b1010, 0b0111, 0b1011, 0b1101, 0b1110];
  const memo = new Map();
  const count = (col, mask) => {
    if (col === n) return mask === 0 ? 1 : 0;
    if ((mask & 3) === 3) return count(col + 1, mask >> 2);
    const key = col * 16 + mask;
    if (memo.has(key)) return memo.get(key);
    const first = (mask & 1) ? 2 : 1;
    let total = 0;
    for (const piece of pieces) {
      if (!(piece & first)) continue;
      if (piece & mask) continue;
      if ((piece & 12) && col + 1 >= n) continue;
      total = (total + count(col, mask | piece)) % MOD;
    }
    memo.set(key, total);
    return total;
  };
  return count(0, 0);
}

